 115:     rem.u32 %r_kw_tmp, %r_rem_ck, %rKW;           // kw = rem % KW
 116:     // Compute global weight index: (((co0*Cin + c)*KH + kh)*KW + kw)
 117:     mul.lo.u32 %r_t2, %r_co0, %rCin;
 118:     add.u32 %r_t2, %r_t2, %r_c_tmp;
 119:     mul.lo.u32 %r_t2, %r_t2, %rKH;
 120:     add.u32 %r_t2, %r_t2, %r_kh_tmp;
 121:     mul.lo.u32 %r_t2, %r_t2, %rKW;
 122:     add.u32 %r_t2, %r_t2, %r_kw_tmp;
 123:     mul.wide.u32 %ofs_bytes, %r_t2, 4;
 124:     add.s64 %addr_w, %rd_w, %ofs_bytes;
 125:     // Use asynchronous copy to stage weights into shared memory
 126:     // Store into shared memory at smem_w[idx] via cp.async
 127:     mul.wide.u32 %ofs_bytes, %r_load_idx, 4;
 128:     add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
 129:     cp.async.ca.shared.global [%addr_smem], [%addr_w], 4;
 130:     add.u32 %r_load_idx, %r_load_idx, %r_tmp1;    // idx += blockDim.x
 131:     bra L_sload_loop;
 132: L_sload_done:
 133:     // Commit and wait for async copies before proceeding
 134:     cp.async.commit_group;
 135:     cp.async.wait_group 0;
 136:     bar.sync 0;
 137:     // Early-exit after cooperative weight staging to avoid barrier divergence
 138:     setp.ge.u32 %p_exit, %r_tid, %r_total;
 139:     @%p_exit bra DONE;
 140:     // acc = bias[co]
 141:     mul.wide.u32 %ofs_bytes, %r_co, 4;
 142:     add.s64 %addr_bias, %rd_b, %ofs_bytes;
 143:     ld.global.f32 %f_bias, [%addr_bias];
 144:     mov.f32 %f_acc, %f_bias;
 145:     // wbase = (int)wo * stride_w - (int)pad_w
 146:     mul.lo.u32 %r_t0, %r_wo, %rSw;
 147:     cvt.s32.u32 %r_t1, %r_t0;
 148:     cvt.s32.u32 %r_t2, %rPw;
 149:     sub.s32 %r_wbase_s32, %r_t1, %r_t2;
 150:     // hbase = (int)ho * stride_h - (int)pad_h
 151:     mul.lo.u32 %r_t0, %r_ho, %rSh;
 152:     cvt.s32.u32 %r_t1, %r_t0;
 153:     cvt.s32.u32 %r_t2, %rPh;
 154:     sub.s32 %r_hbase_s32, %r_t1, %r_t2;
 155:     // Determine if this thread shares co with CTA base (enables shared-memory weights)
 156:     setp.eq.u32 %p_same, %r_co, %r_co0;
 157:     // Precompute kw_lo and kw_hi once (independent of kh)
 158:     mov.u32 %r_kw_lo, 0;
 159:     setp.lt.s32 %p, %r_wbase_s32, 0;
 160:     sub.s32 %r_tmpk0, 0, %r_wbase_s32;
 161:     cvt.u32.s32 %r_tmpk1, %r_tmpk0;
 162:     @!%p bra L_kwlo_once_done;
 163:     setp.gt.u32 %p, %r_tmpk1, %rKW;
 164:     @%p mov.u32 %r_kw_lo, %rKW;
 165:     @!%p mov.u32 %r_kw_lo, %r_tmpk1;
 166:     bra L_kwlo_once_done;
 167: L_kwlo_once_done:
 168:     cvt.s32.u32 %r_t4, %rWin;
 169:     sub.s32 %r_tmpk0, %r_t4, %r_wbase_s32;
 170:     setp.le.s32 %p, %r_tmpk0, 0;
 171:     @%p mov.u32 %r_kw_hi, 0;
 172:     @%p bra L_kwhi_once_done;
 173:     cvt.u32.s32 %r_tmpk1, %r_tmpk0;
 174:     setp.gt.u32 %p, %r_tmpk1, %rKW;
 175:     @%p mov.u32 %r_kw_hi, %rKW;
 176:     @!%p mov.u32 %r_kw_hi, %r_tmpk1;
 177: L_kwhi_once_done:
 178:     // Fast path if Cin == 3: unroll channel loop
 179:     setp.eq.u32 %p_cin3, %rCin, 3;
 180:     @%p_cin3 bra L_fast_cin3;
 181:     // Loop over input channels c (generic path)
 182:     mov.u32 %r_c, 0;
 183: L_c_loop:
 184:     setp.ge.u32 %p, %r_c, %rCin;
 185:     @%p bra L_end_c;
 186:     // (co*Cin + c)
 187:     mul.lo.u32 %r_w_cc, %r_co, %rCin;
 188:     add.u32 %r_w_cc, %r_w_cc, %r_c;
 189:     // idx_nc = n*Cin + c
 190:     mul.lo.u32 %r_idx_nc, %r_n, %rCin;
 191:     add.u32 %r_idx_nc, %r_idx_nc, %r_c;
 192:     // Loop over kernel height kh
 193:     mov.u32 %r_kh, 0;
 194: L_kh_loop:
 195:     setp.ge.u32 %p, %r_kh, %rKH;
 196:     @%p bra L_end_kh;
 197:     // h_in = hbase + kh
 198:     cvt.s32.u32 %r_t0, %r_kh;
 199:     add.s32 %r_hin_s32, %r_hbase_s32, %r_t0;
 200:     // if (h_in < 0 || h_in >= Hin) skip inner loop
 201:     setp.lt.s32 %p, %r_hin_s32, 0;
 202:     @%p bra L_skip_h;
 203:     cvt.s32.u32 %r_t1, %rHin;
 204:     setp.ge.s32 %p, %r_hin_s32, %r_t1;
 205:     @%p bra L_skip_h;
 206:     // in_base = ((idx_nc * Hin) + (u32)h_in) * Win
 207:     mul.lo.u32 %r_idx_nch, %r_idx_nc, %rHin;
 208:     cvt.u32.s32 %r_t2, %r_hin_s32;
 209:     add.u32 %r_idx_nch, %r_idx_nch, %r_t2;
 210:     mul.lo.u32 %r_in_base, %r_idx_nch, %rWin;
 211:     // w_base_idx for global path: (((co*Cin + c) * KH) + kh) * KW
 212:     mul.lo.u32 %r_w_cch, %r_w_cc, %rKH;
 213:     add.u32 %r_w_cch, %r_w_cch, %r_kh;
 214:     mul.lo.u32 %r_w_base_idx, %r_w_cch, %rKW;
 215:     // w_local_base_idx for shared path: (((c) * KH) + kh) * KW
 216:     mul.lo.u32 %r_t3, %r_c, %rKH;
 217:     add.u32 %r_t3, %r_t3, %r_kh;
 218:     mul.lo.u32 %r_w_local_base_idx, %r_t3, %rKW;
 219:     // Loop over kernel width kw in [kw_lo, kw_hi)
 220:     mov.u32 %r_kw, %r_kw_lo;
 221: L_kw_loop:
 222: L_kw_vec_loop:
 223:     // If we have at least 4 elements remaining, and input address is 16B-aligned, use vectorized loads
 224:     add.u32 %r_kwp4, %r_kw, 4;
 225:     setp.gt.u32 %p, %r_kwp4, %r_kw_hi;
 226:     @%p bra L_kw_scalar_entry;
 227:     // Compute E = in_base + (wbase + kw) and check 16B alignment (E % 4 == 0)
 228:     cvt.s32.u32 %r_t3, %r_kw;
 229:     add.s32 %r_win_s32, %r_wbase_s32, %r_t3;
 230:     cvt.u32.s32 %r_win_u32, %r_win_s32;
 231:     add.u32 %r_t5, %r_in_base, %r_win_u32; // E
 232:     and.b32 %r_align, %r_t5, 3;
 233:     setp.ne.u32 %p, %r_align, 0;
 234:     @%p bra L_kw_scalar_entry;
 235:     // Vectorized load of 4 input values
 236:     mul.wide.u32 %ofs_bytes, %r_t5, 4;
 237:     add.s64 %addr_inp, %rd_inp, %ofs_bytes;
 238:     ld.global.v4.f32 {%f_in, %f_v1, %f_v2, %f_v3}, [%addr_inp];
 239:     // Prepare base indices for weights
 240:     add.u32 %r_wloc_base_kw, %r_w_local_base_idx, %r_kw;
 241:     add.u32 %r_wglob_base_kw, %r_w_base_idx, %r_kw;
 242:     // Load 4 weights (shared if same co, else global) and accumulate
 243:     // k = 0
 244:     add.u32 %r_t0, %r_wloc_base_kw, 0;
 245:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 246:     add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
 247:     add.u32 %r_t0, %r_wglob_base_kw, 0;
 248:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 249:     add.s64 %addr_w, %rd_w, %ofs_bytes;
 250:     @%p_same ld.shared.f32 %f_w0, [%addr_smem];
 251:     @!%p_same ld.global.f32 %f_w0, [%addr_w];
 252:     // k = 1
 253:     add.u32 %r_t0, %r_wloc_base_kw, 1;
 254:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 255:     add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
 256:     add.u32 %r_t0, %r_wglob_base_kw, 1;
 257:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 258:     add.s64 %addr_w, %rd_w, %ofs_bytes;
 259:     @%p_same ld.shared.f32 %f_w1, [%addr_smem];
 260:     @!%p_same ld.global.f32 %f_w1, [%addr_w];
 261:     // k = 2
 262:     add.u32 %r_t0, %r_wloc_base_kw, 2;
 263:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 264:     add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
 265:     add.u32 %r_t0, %r_wglob_base_kw, 2;
 266:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 267:     add.s64 %addr_w, %rd_w, %ofs_bytes;
 268:     @%p_same ld.shared.f32 %f_w2, [%addr_smem];
 269:     @!%p_same ld.global.f32 %f_w2, [%addr_w];
 270:     // k = 3
 271:     add.u32 %r_t0, %r_wloc_base_kw, 3;
 272:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 273:     add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
 274:     add.u32 %r_t0, %r_wglob_base_kw, 3;
 275:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 276:     add.s64 %addr_w, %rd_w, %ofs_bytes;
 277:     @%p_same ld.shared.f32 %f_w3, [%addr_smem];
 278:     @!%p_same ld.global.f32 %f_w3, [%addr_w];
 279:     // Accumulate 4 FMAs
 280:     fma.rn.f32 %f_acc, %f_in,  %f_w0, %f_acc;
 281:     fma.rn.f32 %f_acc, %f_v1,  %f_w1, %f_acc;
 282:     fma.rn.f32 %f_acc, %f_v2,  %f_w2, %f_acc;
 283:     fma.rn.f32 %f_acc, %f_v3,  %f_w3, %f_acc;
 284:     // Advance kw by 4 and continue vector loop
 285:     add.u32 %r_kw, %r_kw, 4;
 286:     bra L_kw_vec_loop;
 287: L_kw_scalar_entry:
 288: L_kw_scalar_loop:
 289:     setp.ge.u32 %p, %r_kw, %r_kw_hi;
 290:     @%p bra L_end_kw;
 291:     // Scalar iteration for remaining kw values
 292:     cvt.s32.u32 %r_t3, %r_kw;
 293:     add.s32 %r_win_s32, %r_wbase_s32, %r_t3;
 294:     cvt.u32.s32 %r_win_u32, %r_win_s32;
 295:     add.u32 %r_t5, %r_in_base, %r_win_u32;
 296:     mul.wide.u32 %ofs_bytes, %r_t5, 4;
 297:     add.s64 %addr_inp, %rd_inp, %ofs_bytes;
 298:     ld.global.f32 %f_in, [%addr_inp];
 299:     // Shared-memory address for weights: smem_w[w_local_base_idx + kw]
 300:     add.u32 %r_t0, %r_w_local_base_idx, %r_kw;
 301:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 302:     add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
 303:     // Global-memory address for weights: w[w_base_idx + kw]
 304:     add.u32 %r_t0, %r_w_base_idx, %r_kw;
 305:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 306:     add.s64 %addr_w, %rd_w, %ofs_bytes;
 307:     @%p_same ld.shared.f32 %f_w, [%addr_smem];
 308:     @!%p_same ld.global.f32 %f_w,  [%addr_w];
 309:     fma.rn.f32 %f_acc, %f_in, %f_w, %f_acc;
 310:     add.u32 %r_kw, %r_kw, 1;
 311:     bra L_kw_scalar_loop;
 312: L_end_kw:
 313: L_skip_h:
 314:     add.u32 %r_kh, %r_kh, 1;
 315:     bra L_kh_loop;
 316: L_end_kh:
 317:     add.u32 %r_c, %r_c, 1;
 318:     bra L_c_loop;
 319: L_end_c:
 320: L_store:
 321:     // Store result to output: ((((n*Cout)+co)*Hout + ho)*Wout + wo)
 322:     mul.lo.u32 %r_t0, %r_n, %rCout;
 323:     add.u32 %r_t0, %r_t0, %r_co;
 324:     mul.lo.u32 %r_t0, %r_t0, %rHout;
 325:     add.u32 %r_t0, %r_t0, %r_ho;
 326:     mul.lo.u32 %r_t0, %r_t0, %rWout;
 327:     add.u32 %r_t0, %r_t0, %r_wo;
 328:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 329:     add.s64 %addr_out, %rd_out, %ofs_bytes;
 330:     st.global.f32 [%addr_out], %f_acc;
 331:     bra DONE;
 332:     // Fast path for Cin==3, unrolled over channels
 333: L_fast_cin3:
 334:     // Precompute n*Cin base
 335:     mul.lo.u32 %r_idx_nc_base, %r_n, %rCin; // Cin is 3 here
 336:     // Loop over kernel height kh
 337:     mov.u32 %r_kh, 0;
 338: L_kh_loop_f:
 339:     setp.ge.u32 %p, %r_kh, %rKH;
 340:     @%p bra L_end_kh_f;
 341:     // h_in = hbase + kh
 342:     cvt.s32.u32 %r_t0, %r_kh;
 343:     add.s32 %r_hin_s32, %r_hbase_s32, %r_t0;
 344:     // Bounds check on h_in
 345:     setp.lt.s32 %p, %r_hin_s32, 0;
 346:     @%p bra L_skip_h_f;
 347:     cvt.s32.u32 %r_t1, %rHin;
 348:     setp.ge.s32 %p, %r_hin_s32, %r_t1;
 349:     @%p bra L_skip_h_f;
 350:     // Compute in_base for c0,c1,c2
 351:     cvt.u32.s32 %r_t2, %r_hin_s32;
 352:     // c0
 353:     mul.lo.u32 %r_idx_nch_c0, %r_idx_nc_base, %rHin;
 354:     add.u32 %r_idx_nch_c0, %r_idx_nch_c0, %r_t2;
 355:     mul.lo.u32 %r_in_base_c0, %r_idx_nch_c0, %rWin;
 356:     // c1
 357:     add.u32 %r_t0, %r_idx_nc_base, 1;
 358:     mul.lo.u32 %r_idx_nch_c1, %r_t0, %rHin;
 359:     add.u32 %r_idx_nch_c1, %r_idx_nch_c1, %r_t2;
 360:     mul.lo.u32 %r_in_base_c1, %r_idx_nch_c1, %rWin;
 361:     // c2
 362:     add.u32 %r_t0, %r_idx_nc_base, 2;
 363:     mul.lo.u32 %r_idx_nch_c2, %r_t0, %rHin;
 364:     add.u32 %r_idx_nch_c2, %r_idx_nch_c2, %r_t2;
 365:     mul.lo.u32 %r_in_base_c2, %r_idx_nch_c2, %rWin;
 366:     // Compute weight base indices for c0,c1,c2 (global and shared-local)
 367:     mul.lo.u32 %r_t0, %r_co, %rCin; // co*Cin
 368:     // c0
 369:     add.u32 %r_t1, %r_t0, 0;
 370:     mul.lo.u32 %r_t1, %r_t1, %rKH;
 371:     add.u32 %r_t1, %r_t1, %r_kh;
 372:     mul.lo.u32 %r_w_base_idx_c0, %r_t1, %rKW;
 373:     mul.lo.u32 %r_t3, 0, %rKH;
 374:     add.u32 %r_t3, %r_t3, %r_kh;
 375:     mul.lo.u32 %r_w_local_base_idx_c0, %r_t3, %rKW;
 376:     // c1
 377:     add.u32 %r_t1, %r_t0, 1;
 378:     mul.lo.u32 %r_t1, %r_t1, %rKH;
 379:     add.u32 %r_t1, %r_t1, %r_kh;
 380:     mul.lo.u32 %r_w_base_idx_c1, %r_t1, %rKW;
 381:     mul.lo.u32 %r_t3, 1, %rKH;
 382:     add.u32 %r_t3, %r_t3, %r_kh;
 383:     mul.lo.u32 %r_w_local_base_idx_c1, %r_t3, %rKW;
 384:     // c2
 385:     add.u32 %r_t1, %r_t0, 2;
 386:     mul.lo.u32 %r_t1, %r_t1, %rKH;
 387:     add.u32 %r_t1, %r_t1, %r_kh;
 388:     mul.lo.u32 %r_w_base_idx_c2, %r_t1, %rKW;
 389:     mul.lo.u32 %r_t3, 2, %rKH;
 390:     add.u32 %r_t3, %r_t3, %r_kh;
 391:     mul.lo.u32 %r_w_local_base_idx_c2, %r_t3, %rKW;
 392:     // Loop over kw with vectorized inner when possible
 393:     mov.u32 %r_kw, %r_kw_lo;
 394: L_kw_loop_f:
 395: L_kw_vec_loop_f:
 396:     add.u32 %r_kwp4, %r_kw, 4;
 397:     setp.gt.u32 %p, %r_kwp4, %r_kw_hi;
 398:     @%p bra L_kw_scalar_entry_f;
 399:     // Compute base input offset win_u32 and alignment using c0 stream
 400:     cvt.s32.u32 %r_t3, %r_kw;
 401:     add.s32 %r_win_s32, %r_wbase_s32, %r_t3;
 402:     cvt.u32.s32 %r_win_u32, %r_win_s32;
 403:     add.u32 %r_t5, %r_in_base_c0, %r_win_u32;
 404:     and.b32 %r_align, %r_t5, 3;
 405:     setp.ne.u32 %p, %r_align, 0;
 406:     @%p bra L_kw_scalar_entry_f;
 407:     // Prepare base indices per channel
 408:     add.u32 %r_wloc_base_kw_c0, %r_w_local_base_idx_c0, %r_kw;
 409:     add.u32 %r_wglob_base_kw_c0, %r_w_base_idx_c0, %r_kw;
 410:     add.u32 %r_wloc_base_kw_c1, %r_w_local_base_idx_c1, %r_kw;
 411:     add.u32 %r_wglob_base_kw_c1, %r_w_base_idx_c1, %r_kw;
 412:     add.u32 %r_wloc_base_kw_c2, %r_w_local_base_idx_c2, %r_kw;
 413:     add.u32 %r_wglob_base_kw_c2, %r_w_base_idx_c2, %r_kw;
 414:     // Channel 0: load v4 inputs
 415:     mul.wide.u32 %ofs_bytes, %r_t5, 4;
 416:     add.s64 %addr_inp, %rd_inp, %ofs_bytes;
 417:     ld.global.v4.f32 {%f_in, %f_v1, %f_v2, %f_v3}, [%addr_inp];
 418:     // Load 4 weights for c0 and accumulate
 419:     // k=0
 420:     add.u32 %r_t0, %r_wloc_base_kw_c0, 0;
 421:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 422:     add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
 423:     add.u32 %r_t0, %r_wglob_base_kw_c0, 0;
 424:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 425:     add.s64 %addr_w, %rd_w, %ofs_bytes;
 426:     @%p_same ld.shared.f32 %f_w0, [%addr_smem];
 427:     @!%p_same ld.global.f32 %f_w0, [%addr_w];
 428:     // k=1
 429:     add.u32 %r_t0, %r_wloc_base_kw_c0, 1;
 430:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 431:     add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
 432:     add.u32 %r_t0, %r_wglob_base_kw_c0, 1;
 433:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 434:     add.s64 %addr_w, %rd_w, %ofs_bytes;
 435:     @%p_same ld.shared.f32 %f_w1, [%addr_smem];
 436:     @!%p_same ld.global.f32 %f_w1, [%addr_w];
 437:     // k=2
 438:     add.u32 %r_t0, %r_wloc_base_kw_c0, 2;
 439:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 440:     add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
 441:     add.u32 %r_t0, %r_wglob_base_kw_c0, 2;
 442:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 443:     add.s64 %addr_w, %rd_w, %ofs_bytes;
 444:     @%p_same ld.shared.f32 %f_w2, [%addr_smem];
 445:     @!%p_same ld.global.f32 %f_w2, [%addr_w];
 446:     // k=3
 447:     add.u32 %r_t0, %r_wloc_base_kw_c0, 3;
 448:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
 449:     add.s64 %addr_smem, %rd_smem_base, %ofs_bytes;
 450:     add.u32 %r_t0, %r_wglob_base_kw_c0, 3;
 451:     mul.wide.u32 %ofs_bytes, %r_t0, 4;
